import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Wiki synchronization mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"release/wiki-sync.md","filePath":"release/wiki-sync.md"}'),s={name:"release/wiki-sync.md"};function o(r,e,c,h,l,d){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="wiki-synchronization-mechanics" tabindex="-1">Wiki synchronization mechanics <a class="header-anchor" href="#wiki-synchronization-mechanics" aria-label="Permalink to &quot;Wiki synchronization mechanics&quot;">​</a></h1><p><code>tools/sync_wiki.sh</code> - the docs/ tree also lives on the GitHub Wiki.</p><h2 id="what-syncs" tabindex="-1">What syncs <a class="header-anchor" href="#what-syncs" aria-label="Permalink to &quot;What syncs&quot;">​</a></h2><p>The Wiki gets the curated page set (Home, Getting Started, Building, Architecture Overview, Debugging &amp; QEMU, L1 Extension Guide, User Manual, FAQ, Release Notes, plus the per-domain manuals) rendered from the same <code>docs/</code> sources - one authoring surface, two outputs (docs center on the website, Wiki on GitHub).</p><h2 id="how" tabindex="-1">How <a class="header-anchor" href="#how" aria-label="Permalink to &quot;How&quot;">​</a></h2><ol><li>The script maps <code>docs/</code> pages onto Wiki page names (the mapping table lives in the script).</li><li>Rewrites relative links to Wiki page links.</li><li>Clones <code>{repo}.wiki</code>, writes the pages, commits, pushes.</li></ol><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><ul><li>Every mapped Wiki page exists (the script prints the list).</li><li>Link check: no red links among the mapped set.</li><li>Content equality: the Wiki page and the docs page render the same markdown source (the script diffs them before pushing).</li></ul><h2 id="when-it-runs" tabindex="-1">When it runs <a class="header-anchor" href="#when-it-runs" aria-label="Permalink to &quot;When it runs&quot;">​</a></h2><p>At release time (after docs/ changes land) and on demand for docs- only updates.</p>',10)])])}const m=i(s,[["render",o]]);export{u as __pageData,m as default};
